"""Clock abstraction so scheduling logic can be tested without real sleeps."""
import time


class Clock:
    """Wraps time.monotonic so callers never observe wall-clock jumps
    (e.g. from NTP adjustments or DST changes) as elapsed time.
    """

    def now(self) -> float:
        return time.monotonic()

    def sleep(self, seconds: float) -> None:
        if seconds > 0:
            time.sleep(seconds)


class FakeClock(Clock):
    """Deterministic clock for unit tests: time only advances when told to."""

    def __init__(self, start: float = 0.0) -> None:
        self._now = start

    def now(self) -> float:
        return self._now

    def sleep(self, seconds: float) -> None:
        if seconds > 0:
            self._now += seconds

    def advance(self, seconds: float) -> None:
        self._now += seconds
